17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
107	        if (ownerAlreadyExists(owner) || emailAlreadyExists(owner)) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        if (owner.getRegistrationDate() == null) {
111	            owner.setRegistrationDate(LocalDate.now());
112	        }
113	        owner.setCity(resolveCity(owner.getCity()));
114	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
115	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
116	        this.clinicService.saveOwner(owner);
117	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
118	        headers.setLocation(UriComponentsBuilder.newInstance()
119	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
120	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
121	    }
122	
123	    /**
124	     * Resolves the city to store for a newly created owner. If another owner is already stored in
125	     * the same city (compared ignoring letter case), that existing owner's exact spelling of the
126	     * city name is reused so that a single city is always represented consistently. Otherwise the
127	     * supplied city is title-cased (see {@link #titleCase(String)}) before being stored.
128	     *
129	     * @param city the raw city supplied for the owner being created, may be {@code null}
130	     * @return the city to store, or {@code null} if {@code city} is {@code null}
131	     */
132	    private String resolveCity(String city) {
133	        if (city == null) {
134	            return null;
135	        }
136	        return this.clinicService.findAllOwners().stream()
137	            .map(Owner::getCity)
138	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
139	            .findFirst()
140	            .orElseGet(() -> titleCase(city));
141	    }
142	
143	    /**
144	     * Title-cases a value so that the first letter of every whitespace-separated word is
145	     * upper-cased and every other letter is lower-cased, preserving the original whitespace. For
146	     * example {@code "new  york"} becomes {@code "New  York"} and {@code "LONDON"} becomes
147	     * {@code "London"}.
148	     *
149	     * @param value the raw value, may be {@code null}
150	     * @return the title-cased value, or {@code null} if {@code value} is {@code null}
151	     */
152	    private static String titleCase(String value) {
153	        if (value == null) {
154	            return null;
155	        }
156	        StringBuilder result = new StringBuilder(value.length());
157	        boolean startOfWord = true;
158	        for (int i = 0; i < value.length(); i++) {
159	            char c = value.charAt(i);
160	            if (Character.isWhitespace(c)) {
161	                startOfWord = true;
162	                result.append(c);
163	            } else {
164	                result.append(startOfWord ? Character.toUpperCase(c) : Character.toLowerCase(c));
165	                startOfWord = false;
166	            }
167	        }
168	        return result.toString();
169	    }
170	
171	    /**
172	     * Builds the customer code for a newly created owner in the given city, formatted as
173	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number of owners
174	     * already stored in that city, zero-padded to four digits (e.g. {@code LONDON-0007}). The
175	     * count of existing owners in the city ignores letter case.
176	     *
177	     * @param city the city of the owner being created
178	     * @return the assigned customer code
179	     */
180	    private String nextCustomerCode(String city) {
181	        long ownersInCity = this.clinicService.findAllOwners().stream()
182	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
183	            .count();
184	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
185	    }
186	
187	    /**
188	     * Determines whether an owner already exists using the same telephone number.
189	     * Comparison ignores letter case and surrounding or repeated whitespace.
190	     *
191	     * @param owner the candidate owner to check
192	     * @return {@code true} if any other owner with the same telephone is already stored
193	     */
194	    private boolean ownerAlreadyExists(Owner owner) {
195	        String telephone = normalizeTelephone(owner.getTelephone());
196	        return this.clinicService.findAllOwners().stream()
197	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
198	    }
199	
200	    /**
201	     * Normalizes a telephone number to digits only, stripping spaces, dashes and
202	     * parentheses (any non-digit character). This is the canonical stored form and is
203	     * used for the telephone-uniqueness check, so {@code "(613) 555-0100"} and
204	     * {@code "6135550100"} are treated as the same number.
205	     *
206	     * @param telephone the raw telephone value, may be {@code null}
207	     * @return the digits-only value, or {@code null} if {@code telephone} is {@code null}
208	     */
209	    private static String normalizeTelephone(String telephone) {
210	        if (telephone == null) {
211	            return null;
212	        }
213	        return telephone.replaceAll("[^0-9]", "");
214	    }
215	
216	    /**
217	     * Determines whether another owner already uses the same email address.
218	     * Owners without an email are ignored, so a missing email never conflicts.
219	     * Comparison ignores letter case and surrounding or repeated whitespace.
220	     *
221	     * @param owner the candidate owner to check
222	     * @return {@code true} if the candidate supplies an email already used by a stored owner
223	     */
224	    private boolean emailAlreadyExists(Owner owner) {
225	        String email = normalize(owner.getEmail());
226	        if (email == null || email.isEmpty()) {
227	            return false;
228	        }
229	        return this.clinicService.findAllOwners().stream()
230	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
231	    }
232	
233	    /**
234	     * Normalizes a value for duplicate detection so that comparisons ignore letter
235	     * case and surrounding or repeated whitespace. Leading and trailing whitespace is
236	     * trimmed, any run of internal whitespace is collapsed to a single space, and the
237	     * result is lower-cased. For example {@code "  john   smith "} and {@code "John Smith"}
238	     * both normalize to {@code "john smith"}.
239	     *
240	     * @param value the raw value, may be {@code null}
241	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
242	     */
243	    private static String normalize(String value) {
244	        if (value == null) {
245	            return null;
246	        }
247	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
248	    }
249	
250	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
251	    @Override
252	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
253	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
254	        if (currentOwner == null) {
255	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	        }
257	        currentOwner.setAddress(ownerFieldsDto.getAddress());
258	        currentOwner.setCity(ownerFieldsDto.getCity());
259	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
260	        currentOwner.setLastName(ownerFieldsDto.getLastName());
261	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
262	        this.clinicService.saveOwner(currentOwner);
263	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
264	    }
265	
266	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
267	    @Transactional
268	    @Override
269	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
270	        Owner owner = this.clinicService.findOwnerById(ownerId);
271	        if (owner == null) {
272	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
273	        }
274	        this.clinicService.deleteOwner(owner);
275	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
276	    }
277	
278	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
279	    @Override
280	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
281	        Owner owner = this.clinicService.findOwnerById(ownerId);
282	        if (owner == null) {
283	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
284	        }
285	        HttpHeaders headers = new HttpHeaders();
286	        Pet pet = petMapper.toPet(petFieldsDto);
287	        owner.setId(ownerId);
288	        pet.setOwner(owner);
289	        pet.getType().setName(null);
290	        this.clinicService.savePet(pet);
291	        PetDto petDto = petMapper.toPetDto(pet);
292	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
293	            .buildAndExpand(pet.getId()).toUri());
294	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
295	    }
296	
297	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
298	    @Override
299	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
300	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
301	        if (currentOwner != null) {
302	            Pet currentPet = this.clinicService.findPetById(petId);
303	            if (currentPet != null) {
